#include <bits/stdc++.h>
using namespace std;

struct BIT {
    int n;
    vector<int> bit;

    BIT(int n = 0) : n(n), bit(n + 1, 0) {}

    void add(int idx, int val) {
        for (; idx <= n; idx += idx & -idx)
            bit[idx] += val;
    }

    int sum(int idx) {
        int res = 0;
        for (; idx > 0; idx -= idx & -idx)
            res += bit[idx];
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long X1, X2;
    cin >> N >> X1 >> X2;

    vector<pair<long long, long long>> pts;
    vector<long long> vals;
    pts.reserve(N);
    vals.reserve(N);

    for (int i = 0; i < N; ++i) {
        long long A, B;
        cin >> A >> B;

        long long y1 = A * X1 + B;
        long long y2 = A * X2 + B;

        pts.push_back({y1, y2});
        vals.push_back(y2);
    }

    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    sort(pts.begin(), pts.end());

    BIT bit((int)vals.size());

    long long ans = 0;
    long long total = 0;

    int i = 0;
    while (i < N) {
        int j = i;
        while (j < N && pts[j].first == pts[i].first)
            ++j;

        long long groupSize = j - i;
        ans += groupSize * (groupSize - 1) / 2;

        for (int k = i; k < j; ++k) {
            long long v = pts[k].second;
            int idx = int(lower_bound(vals.begin(), vals.end(), v) - vals.begin()) + 1;

            int less = bit.sum(idx - 1);
            ans += total - less;
        }

        for (int k = i; k < j; ++k) {
            long long v = pts[k].second;
            int idx = int(lower_bound(vals.begin(), vals.end(), v) - vals.begin()) + 1;
            bit.add(idx, 1);
        }

        total += groupSize;
        i = j;
    }

    cout << ans << '\n';

    return 0;
}
